<script setup>
import {computed,inject,ref} from 'vue';
import {paymentSchedule,nextPayments} from './payments.js';
const data=inject('familyData'),commit=inject('commitFamily'),currency=inject('formatCurrencyInt'),member=inject('currentMember'),notify=inject('showNotification');
const now=new Date(),month=ref(`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`),range=ref('week'),busy=ref('');
const rows=computed(()=>range.value==='week'?nextPayments(data.value):paymentSchedule(data.value,month.value));
const checked=computed(()=>rows.value.filter(r=>data.value.paymentChecks?.[r.id]?.checked).length);
async function toggle(row){busy.value=row.id;try{await commit(d=>{d.paymentChecks||={};if(d.paymentChecks[row.id]?.checked)delete d.paymentChecks[row.id];else d.paymentChecks[row.id]={checked:true,checkedAt:new Date().toISOString(),by:member.value};},{label:'还款计划核对'});}catch(e){notify(e.message);}finally{busy.value='';}}
</script>
<template><section class="payments-panel glass-card"><div class="payments-heading"><div><span class="eyebrow">A LITTLE PEACE OF MIND</span><h2>把接下来的账，心里有数</h2></div><div class="payment-tabs"><button :class="{active:range==='week'}" @click="range='week'">未来 7 天</button><button :class="{active:range==='month'}" @click="range='month'">按月核对</button></div></div><div class="payment-summary"><label v-if="range==='month'">计划月份 <input v-model="month" type="month" required></label><span>{{rows.length}} 项计划 · {{checked}} 项已人工核对</span></div><p class="payment-note">这里记录的是家庭安排。点击“已核对”表示你已自行确认账单，不代表银行执行成功。</p><p v-if="!rows.length" class="payment-empty">这段时间没有待核对的计划，可以安心安排生活。</p><div v-for="row in rows" :key="row.id" class="payment-row"><time>{{row.date.slice(5).replace('-',' / ')}}</time><div><strong>{{row.name}}</strong><p>{{row.type}} · {{row.owner}}</p></div><b>{{currency(row.amount)}}</b><button :disabled="busy===row.id" :class="{done:data.paymentChecks?.[row.id]?.checked}" @click="toggle(row)">{{data.paymentChecks?.[row.id]?.checked?'已核对 ↶':'我已核对'}}</button></div></section></template>
<style scoped>.payments-panel{max-width:1120px;margin:28px auto 36px;padding:28px;border-radius:22px}.payments-heading{display:flex;justify-content:space-between;gap:20px;align-items:center}.payments-heading h2{font-size:20px;margin-top:8px;font-weight:500}.payment-tabs{display:flex;background:#f0ece5;padding:4px;border-radius:12px;white-space:nowrap}.payment-tabs button{min-height:40px;padding:0 14px;font-size:12px;border-radius:9px}.payment-tabs button.active{background:#fffdf9;box-shadow:0 2px 6px #0001}.payment-summary{display:flex;justify-content:space-between;align-items:center;font-size:12px;margin-top:24px;color:#786f64}.payment-summary input{border:1px solid #d9d2c7;padding:6px;background:#fffdf7;border-radius:7px}.payment-note{font-size:11px;color:#8b8071;margin:12px 0 16px}.payment-row{display:flex;gap:22px;align-items:center;border-top:1px solid #eae4db;padding:16px 0}.payment-row time{font-size:13px;color:#8a6c50}.payment-row>div{flex:1}.payment-row strong{font-size:13px;font-weight:500}.payment-row p{font-size:10px;color:#887d70}.payment-row b{font-size:14px;font-weight:500}.payment-row button{font-size:11px;border:1px solid #dcd2c3;border-radius:9px;min-height:40px;padding:0 12px}.payment-row button.done{color:#6e7b64;background:#eff1ea}.payment-empty{padding:24px;text-align:center;font-size:13px;color:#847869}@media(max-width:700px){.payments-panel{padding:20px;margin:20px 16px}.payments-heading{display:block}.payments-heading h2{font-size:18px}.payment-tabs{display:inline-flex;margin-top:16px}.payment-row{flex-wrap:wrap;gap:10px}.payment-row time{width:55px}.payment-row>div{min-width:145px}.payment-row b{margin-left:65px}.payment-row button{margin-left:auto}.payment-summary{gap:10px;flex-wrap:wrap}}</style>
